const body = $input.item.json.body || $input.item.json;
const prj = process.env.HOME + '/Library/Mobile Documents/com~apple~CloudDocs/Kit-Piloto-Automatico-V30-DISTRIB';
const db = `${prj}/IMPAR_OS/database/impar.db`;
const { execSync } = require('child_process');
const ts = new Date().toISOString();
const source = (body.source||'unknown').replace(/'/g,"''").substring(0,100);
const errType = (body.error_type||'unknown').replace(/'/g,"''").substring(0,50);
const msg = (body.message||'').replace(/'/g,"''").substring(0,500);
const ctx = (body.context||'').replace(/'/g,"''").substring(0,200);
try {
  execSync(`sqlite3 "${db}" "INSERT INTO errors (timestamp,source,error_type,message,context,resolved) VALUES ('${ts}','${source}','${errType}','${msg}','${ctx}',0);"`, {timeout:5000});
} catch(e) { return [{ json: { error: e.message.substring(0,200), ai_used: false } }]; }
return [{ json: { ok: true, recorded: true, source, error_type: errType, ai_used: false, timestamp: ts } }];
